    public static Map GetInventDimCollectors(int _addStart, TFMInventDimSetup _inventDimSetup, InventDimParm _inventDimParm, Map _replaceLabels = null, Map _onlineValidationDocuments = null, InventDim _defaultValues = null, boolean _lockValues = false)
    {
        Map									returnMap = new Map(Types::String, Types::Class);
        InventDimGroupSetup					inventDimGroupSetup = InventDimGroupSetup::newInventTable(_inventDimSetup.parmInventTable());
        SysDictType							dictType;
        SysDictField						sdf;
        FieldName							fieldName;
        int									add = _addStart;
        str									labelForField;
        Set									storDims = TFMHelper::fieldGroupToSet(tableNum(InventDim),tableFieldGroupStr(InventDim, StorageDimensions));
        Set									prodDims = TFMHelper::fieldGroupToSet(tableNum(InventDim),tableFieldGroupStr(InventDim, ProductDimensions));
        Set									tracDims = TFMHelper::fieldGroupToSet(tableNum(InventDim),tableFieldGroupStr(InventDim, TrackingDimensions));
        SetEnumerator						sEnum = storDims.getEnumerator();
        TFMRegistrationCollectorList		regCollectorList;
        Map									collectorMap;

        _inventDimParm.InventStatusFlag = NoYes::No; // Never prompt for Status
        if (_inventDimSetup.registerWMSPallet())
        {
            _inventDimParm.WMSLocationIdFlag = NoYes::No; // Never prompt for Location if using Pallet/LP
        }
        while (sEnum.moveNext())
        {
            fieldName = sEnum.current();
            if (!EcoResStorageDimensionGroupFldSetup::findByDimensionGroupFieldId(inventDimGroupSetup.getStorageDimensionGroup(),fieldName2Id(tableNum(InventDim),sEnum.current())).IsActive)
            {
                continue;
            }

            if (!_inventDimParm.(InventDim::dim2dimParm(fieldName2Id(tableNum(InventDim),sEnum.current()))))
            {
                continue;
            }
            sdf = new SysDictField(tableNum(InventDim), fieldName2Id(tableNum(InventDim),sEnum.current()));
            add+=10;
            dictType = new SysDictType(sdf.typeId());
            labelForField = dictType.label();
            if (_replaceLabels != null && _replaceLabels.exists(sdf.name()))
            {
                labelForField = _replaceLabels.lookup(sdf.name());
            }


            if (fieldName == fieldStr(InventDim,InventLocationId))
            {                
				regCollectorList = new TFMRegistrationCollectorList(5,TFMConstants::Warehouse(),"@SYS6437","@SYS6437","@SYS6437"); //TFMRegistrationCollector::collectorFromEDT(extendedtypestr(InventLocationId));

				regCollectorList.parmDataTable(methodStr(TFMGetReferenceData,WarehouseFilterList));
				regCollectorList.parmDataKeyColumn(extendedtypestr(InventLocationId));
				regCollectorList.parmDataDisplayColumn(extendedtypestr(Name));
                collectorMap = regCollectorList.getMap();
            }
            else if (fieldName == fieldStr(InventDim,LicensePlateId))
            {
                collectorMap = TFMRegistrationCollectorText::TextStepMap(false,add,strLwr(sdf.name()),labelForField,labelForField,dictType.help(),dictType.stringLen(),false,'',TFMInventDimHelper::inventDimField2GS1(sdf.name()));
                if (!TFMInventDimSetup::Construct(_inventDimSetup.parmInventTable()).registerLicensePlate())
                {
                    continue; 
                }

            }
			else
            {
                collectorMap = TFMRegistrationCollectorText::TextStepMap(false,add,strLwr(sdf.name()),labelForField,labelForField,dictType.help(),dictType.stringLen(),false,'',TFMInventDimHelper::inventDimField2GS1(sdf.name()));
            }
            if (_onlineValidationDocuments != null && _onlineValidationDocuments.exists(sdf.name()))
            {
                collectorMap.insert('onlineValidationDocument',_onlineValidationDocuments.lookup(sdf.name()));
            }
            if (_defaultValues != null && _defaultValues.(fieldName2Id(tableNum(InventDim),sEnum.current())))
            {
                collectorMap.insert('defaultValue',_defaultValues.(fieldName2Id(tableNum(InventDim),sEnum.current())));
                if (_lockValues)
                {
                    collectorMap.insert('validationValues',_defaultValues.(fieldName2Id(tableNum(InventDim),sEnum.current())));
                }
            }
            returnMap.insert(sdf.name(),collectorMap);

        }

        sEnum = prodDims.getEnumerator();
        while (sEnum.moveNext())
        {
            fieldName = sEnum.current();
            if (!EcoResProductDimGroupSetup::newItemId(_inventDimSetup.parmInventTable().ItemId).getFieldSetup(fieldName2Id(tableNum(InventDim),sEnum.current())).isActive())
            {
                continue;
            }
            if (!_inventDimParm.(fieldName2Id(tableNum(InventDimParm),TFMInventDimHelper::flagFieldName(fieldName))))
            {
                continue;
            }
            sdf = new SysDictField(tableNum(InventDim), fieldName2Id(tableNum(InventDim),sEnum.current()));
            add+=10;
            dictType = new SysDictType(sdf.typeId());
            labelForField = dictType.label();
            if (_replaceLabels != null && _replaceLabels.exists(sdf.name()))
            {
                labelForField = _replaceLabels.lookup(sdf.name());
            }
            collectorMap = TFMRegistrationCollectorList::ListStepMap(false,add, strlwr(sdf.name()) ,labelForField,labelForField,dictType.help(),TFMInventDimHelper::getProductDimensionValues(_inventDimSetup.parminventTable().Product,sEnum.current()),false,'',';',TFMInventDimHelper::inventDimField2GS1(sdf.name()));
            if (_onlineValidationDocuments != null && _onlineValidationDocuments.exists(sdf.name()))
            {
                collectorMap.insert('onlineValidationDocument',_onlineValidationDocuments.lookup(sdf.name()));
            }
            if (_defaultValues != null && _defaultValues.(fieldName2Id(tableNum(InventDim),sEnum.current())))
            {
                collectorMap.insert('defaultValue',_defaultValues.(fieldName2Id(tableNum(InventDim),sEnum.current())));
                if (_lockValues)
                {
                    collectorMap.insert('validationValues',_defaultValues.(fieldName2Id(tableNum(InventDim),sEnum.current())));
                }
            }
			returnMap.insert(sdf.name(),collectorMap);

        }
        sEnum = tracDims.getEnumerator();
        while (sEnum.moveNext())
        {
            fieldName = sEnum.current();
            if (!EcoResTrackingDimensionGroupFldSetup::findByDimensionGroupFieldId(inventDimGroupSetup.getTrackingDimensionGroup(), fieldName2Id(tableNum(InventDim),sEnum.current())).isActive)
            {
                continue;
            }
            if (!_inventDimParm.(fieldName2Id(tableNum(InventDimParm),TFMInventDimHelper::flagFieldName(fieldName))))
            {
                continue;
            }
            sdf = new SysDictField(tableNum(InventDim), fieldName2Id(tableNum(InventDim),sEnum.current()));
            add+=10;
            dictType = new SysDictType(sdf.typeId());
            labelForField = dictType.label();
            if (_replaceLabels != null && _replaceLabels.exists(sdf.name()))
            {
                labelForField = _replaceLabels.lookup(sdf.name());
            }
            collectorMap = TFMRegistrationCollectorText::TextStepMap(false,add,strLwr(sdf.name()),labelForField,labelForField,dictType.help(),dictType.stringLen(),false,'',TFMInventDimHelper::inventDimField2GS1(sdf.name()));
            if (_onlineValidationDocuments != null && _onlineValidationDocuments.exists(sdf.name()))
            {
                collectorMap.insert('onlineValidationDocument',_onlineValidationDocuments.lookup(sdf.name()));
            }
            if (_defaultValues != null && _defaultValues.(fieldName2Id(tableNum(InventDim),sEnum.current())))
            {
                collectorMap.insert('defaultValue',_defaultValues.(fieldName2Id(tableNum(InventDim),sEnum.current())));
                if (_lockValues)
                {
                    collectorMap.insert('validationValues',_defaultValues.(fieldName2Id(tableNum(InventDim),sEnum.current())));
                }
            }
			returnMap.insert(sdf.name(),collectorMap);
        }

        if ((_inventDimParm.(fieldName2id(tableNum(InventDimParm),fieldStr(InventDimParm, inventSerialIdFlag))) && !returnMap.exists(fieldStr(InventDim, inventSerialId)))/* ||
            (_inventDimParm.(fieldName2id(tableNum(InventDimParm),fieldStr(InventDimParm, inventSerialIdFlag))))*/)
        {
            // If serial numbers are not used we ask for a quantity (for serial numbers the quantity is always 1)
            add+=10;
            dictType = new SysDictType(extendedTypeNum(Qty));
            collectorMap = TFMRegistrationCollectorDecimal::DecimalStepMap(add,TFMConstants::Quantity(),"@SYS130676",dictType.label(),'',false,'',0,10000000,14,TFMGS1Table::AIsfromName(TFMConstants::Quantity()));
            if (_onlineValidationDocuments != null && _onlineValidationDocuments.exists(TFMConstants::Quantity()))
            {
                collectorMap.insert('onlineValidationDocument',_onlineValidationDocuments.lookup(TFMConstants::Quantity()));
            }
            returnMap.insert(TFMConstants::Quantity(),collectorMap);
        }


        return returnMap;
    }

    public static Map getStorageDimensions(ItemId _itemId, InventDim _inventDim) 
    {
        Map					returnMap = new Map(Types::String,Types::String);
        InventDimGroupSetup	inventDimGroupSetup = InventDimGroupSetup::newInventTable(InventTable::find(_itemId));
        FieldName			fieldName;
        Set					storDims = TFMHelper::fieldGroupToSet(tableNum(InventDim),tableFieldGroupStr(InventDim, StorageDimensions));
        SetEnumerator		sEnum = storDims.getEnumerator();
        SysDictField		sdf;
        SysDictType			dictType;
        str					labelForField;
		while (sEnum.moveNext())
        {

            fieldName = sEnum.current();

            if (!EcoResStorageDimensionGroupFldSetup::findByDimensionGroupFieldId(inventDimGroupSetup.getStorageDimensionGroup(),fieldName2Id(tableNum(InventDim),sEnum.current())).IsActive)
            {
                continue;
            }
            sdf = new SysDictField(tableNum(InventDim), fieldName2Id(tableNum(InventDim),sEnum.current()));

            dictType = new SysDictType(sdf.typeId());
            labelForField = dictType.label();

            returnMap.insert(labelForField,strFmt('%1',_inventDim.(fieldName2Id(tableNum(InventDim),fieldName))));
        }
        return returnMap;
    }

/// <summary>
/// Returns true if the storage dimension for the WMSLocationID is set to not active.
/// </summary>
/// <param name = "_itemId">The itemId to find the InventDimGroupSetup from</param>
/// <returns>true if the storage dimension for the WMSLocationID is not active.</returns>
public static boolean isStorageDimensionForWMSLocationNotActive(ItemId _itemId)
{
    EcoResStorageDimensionGroupFldSetup wmsLocationIdSetup;
    InventDimGroupSetup	inventDimGroupSetup = InventDimGroupSetup::newInventTable(InventTable::find(_itemId));
    wmsLocationIdSetup = EcoResStorageDimensionGroupFldSetup::findByDimensionGroupFieldId(inventDimGroupSetup.getStorageDimensionGroup(),fieldName2Id(tableNum(InventDim), extendedTypeStr(wMSLocationId)));

    if(!wmsLocationIdSetup || wmsLocationIdSetup.IsActive)
    {
        return false;
    }

    return true;
}

