public static InventDim GetInventDimFromLicensePlate(WHSLicensePlateId _licensePlate)
{
    InventTrans iTrs;
    InventDim   iDim;
    InventSum   iSum;

    select firstonly isum
        join iDim where iDim.inventDimId == isum.InventDimId
        &&   iDim.LicensePlateId == _licensePlate && isum.PhysicalInvent;
    if (iDim)
    {
        return iDim;
    }


    select firstonly iTrs order by DatePhysical desc where iTrs.StatusReceipt != StatusReceipt::None
        join iDim where iDim.LicensePlateId == _licensePlate && iDim.inventDimId == iTrs.inventDimId;

    return iDim  ? iDim : null;
}

public static WMSLocation WmsLocationIdFromLicensePlate(WHSLicensePlateId _licensePlate)
{
    InventDim inventDim = TFMInventDimHelper::GetInventDimFromLicensePlate(_licensePlate);
    if(inventDim && inventDim.RecId)
    {
        return inventDim.wmsLocation();
    }
    return null;
}

public static str flagFieldName(FieldName _inventDimFieldName)
{
    //FieldName   fieldNameFlag;
    int         ruPos = strScan(_inventDimFieldName,'_RU',1,strLen(_inventDimFieldName));
    if (!ruPos)
    {
        return _inventDimFieldName + 'Flag';
    }
    return subStr(_inventDimFieldName,1,strLen(_inventDimFieldName)-3) + 'Flag_RU';
}

public static str inventDimField2GS1(FieldName _inventDimFieldName)
{
    str result = '';
    result = TFMGS1Table::AIsfromField(new SysDictField(tableNum(InventDim),fieldName2Id(tableNum(InventDim),_inventDimFieldName)));
    return result;
}

public static str getProductDimensionValues(RefRecId _product, FieldName _fieldName)
{
    str                             resultValues;
    ecoResProductVariantDimValue    ecoResProductVariantDimValue;
    List                            values;
    ListEnumerator                  enumerator;
    //Common                          prodDimTable;

    ecoResProductVariantDimValue = EcoResProductVariantDimValue::newEcoResProductVariantDimValue(fieldName2Id(tableNum(InventDim),_fieldName));
    values = ecoResProductVariantDimValue.getDimValues(_product);
    enumerator = values.getEnumerator();

    // Generate the list of valid values for this item
    while (enumerator.moveNext())
    {

        resultValues += (resultValues ? ';' : '') + enumerator.current();
    }

    return resultValues;
}

public static void locationMismatch(InventDim _inventDim, InventTransId _inventTransID = '')
{
    InventTrans iTrs;
    InventTransOrigin iOrigin;
    if (!_inventDim.LicensePlateId)
    {
        //Don't correct for non-licenseplate orders.
        return;
    }
    select firstonly iTrs order by RecId desc where iTrs.inventDimId
        join iOrigin where iTrs.InventTransOrigin == iOrigin.recId && iOrigin.InventTransId == _inventTransID;

    if(iOrigin.ReferenceCategory == InventTransType::TransferOrderReceive)
    {
        _inventDim.InventLocationId = iTrs.inventLocationId();            
        _inventDim.wMSLocationId = InventLocation::find(_inventDim.InventLocationId).WMSLocationIdDefaultReceipt;
    }

}

    public static str LpContentHtml(WHSLicensePlateId _licensePlate)
    {
        Set				lpContent = TFMInventDimHelper::LicensePlateDetailedContent(_licensePlate);
        SetEnumerator	sEnum = lpContent.getEnumerator();
		str				html;
        str				imgBase64;
        //Set				itemImg;
        InventSum		iSum;
        html = '<html><body>'+strFmt("@TFM:Licenseplatehasfollowingcontent",_licensePlate)+'<table style="width:100%">';
		while (sEnum.moveNext())
        {
            html += '<tr><td style="width:30%"><img width="95%" src="data:image/png;base64, ';
            iSum = sEnum.current();
            imgBase64 = TFMHelper::imageIDFromDocuref(TFMHelper::FindItemDocuref(iSum.itemId,iSum.InventDimId));
            imgBase64 = TFMDocGetMedia::getBase64FromName(imgBase64);
            html += imgBase64+'" /></td><td><b>'+iSum.ItemId + '</b><br><i>' +iSum.itemName()+'</i><br><u>'+ strFmt('%1 %2',iSum.PhysicalInvent,iSum.inventTable().inventUnitId()) + '</u></td></tr>';
        }
        html += '</table></body></html>';
        return html;
    }

    public static Set LicensePlateDetailedContent(WHSLicensePlateId _LicensePlate)
    {
        InventSum       iSum;
        InventDim       InventDim;
        Set             items = new Set(Types::Record);

        while select InventDim
            where InventDim.LicensePlateId == _LicensePlate
        join iSum
            where iSum.InventDimId     == InventDim.InventDimId    &&
                  iSum.Closed          == NoYes::No && iSum.PhysicalInvent
        {
            items.add(iSum);

        }
		return items;
    }

public static Map LicensePlateContent(WHSLicensePlateId _LicensePlate)
{
    InventSum       iSum;
    InventDim       InventDim;
    Map             itemIDs = new Map(Types::String,Types::Real);

    while select InventDim
        where InventDim.LicensePlateId == _LicensePlate
    join iSum
        where iSum.InventDimId     == InventDim.InventDimId    &&
              iSum.Closed          == NoYes::No && iSum.PhysicalInvent
    {
        itemIDs.insert(iSum.ItemId, (itemIDs.exists(iSum.ItemId) ? itemIDs.lookup(iSum.ItemId) : 0) + iSum.PhysicalInvent);            
    }
    return itemIDs;
}

    public static InventDim getInventDim(InventDim _iDim,
                                        ItemId _itemid,
                                        TFMRequestInventDimElement _request, str _prefix = '')
    {
        //* iDim can be initialized with values - prior to call.
        #tfm
        InventTable         inventTable = InventTable::find(_ItemId);        
        TFMInventDimSetup   tfmInventDimSetup;
        SysDictClass        dc = new SysDictClass(classIdGet(_request));
        FieldName           fieldName;
        InventDim           inventDim = _iDim;
        Set                 storDims = TFMHelper::fieldGroupToSet(tableNum(InventDim),tableFieldGroupStr(InventDim, StorageDimensions));
        Set                 prodDims = TFMHelper::fieldGroupToSet(tableNum(InventDim),tableFieldGroupStr(InventDim, ProductDimensions));
        Set                 tracDims = TFMHelper::fieldGroupToSet(tableNum(InventDim),tableFieldGroupStr(InventDim, TrackingDimensions));
        InventDimGroupSetup inventDimGroupSetup = InventDimGroupSetup::newInventTable(inventTable);
        tfmInventDimSetup = TFMInventDimSetup::Construct(inventTable);
        SetEnumerator       sEnum = storDims.getEnumerator();
        while (sEnum.moveNext())
        {
            fieldName = sEnum.current();
            if (!EcoResStorageDimensionGroupFldSetup::findByDimensionGroupFieldId(inventDimGroupSetup.getStorageDimensionGroup(),fieldName2Id(tableNum(InventDim),sEnum.current())).IsActive)
            {
                continue;
            }            
            if (_prefix && dc.hasObjectMethod('parm' + _prefix + sEnum.current())) 
            {
                inventDim.(fieldName2Id(tableNum(InventDim),sEnum.current())) = dc.callObject('parm'+ _prefix + sEnum.current(), _request);
            }
            if (!inventDim.(fieldName2Id(tableNum(InventDim),sEnum.current())) && dc.hasObjectMethod('parm' + sEnum.current()))
            {
                inventDim.(fieldName2Id(tableNum(InventDim),sEnum.current())) = dc.callObject('parm'+ sEnum.current(), _request);
            }
            if (! inventDim.(fieldName2Id(tableNum(InventDim),sEnum.current())) && _request.getFieldMap().exists(sEnum.current()))
            {
                inventDim.(fieldName2Id(tableNum(InventDim),sEnum.current())) = _request.getFieldValue(sEnum.current());
            }
            if (_prefix && !inventDim.(fieldName2Id(tableNum(InventDim),sEnum.current())) && _request.getFieldMap().exists(_prefix + sEnum.current()))
            {
                inventDim.(fieldName2Id(tableNum(InventDim),sEnum.current())) = _request.getFieldValue(_prefix + sEnum.current());
			}
        }
        sEnum  = prodDims.getEnumerator();
        while (sEnum.moveNext())
        {
            fieldName = sEnum.current();
            if (!EcoResProductDimGroupSetup::newItemId(_ItemId).getFieldSetup(fieldName2Id(tableNum(InventDim),sEnum.current())).isActive())
            {
                continue;
            }
            if (_prefix && dc.hasObjectMethod('parm' + _prefix + sEnum.current()))
            {
                inventDim.(fieldName2Id(tableNum(InventDim),sEnum.current())) = dc.callObject('parm'+ _prefix + sEnum.current(), _request);
            }
            else if (_prefix && _request.getFieldMap().exists(_prefix + sEnum.current()))
            {
                inventDim.(fieldName2Id(tableNum(InventDim),sEnum.current())) = _request.getFieldValue(_prefix + sEnum.current());
            }
            if (inventDim.(fieldName2Id(tableNum(InventDim),sEnum.current())))
            {
				//Already have a value
                continue;
            }

            if (dc.hasObjectMethod('parm' + sEnum.current()))
            {
                inventDim.(fieldName2Id(tableNum(InventDim),sEnum.current())) = dc.callObject('parm' + sEnum.current(), _request);
            }
            else if (_request.getFieldMap().exists(sEnum.current()))
            {
                inventDim.(fieldName2Id(tableNum(InventDim),sEnum.current())) = _request.getFieldValue(sEnum.current());
            }

        }
        sEnum  = tracDims.getEnumerator();
        while (sEnum.moveNext())
        {
            fieldName = sEnum.current();
            if (!EcoResTrackingDimensionGroupFldSetup::findByDimensionGroupFieldId(inventDimGroupSetup.getTrackingDimensionGroup(), fieldName2Id(tableNum(InventDim),sEnum.current())).isActive)
            {
                continue;
            }
            if (_prefix && dc.hasObjectMethod('parm' + _prefix + sEnum.current()))
            {
                inventDim.(fieldName2Id(tableNum(InventDim),sEnum.current())) = dc.callObject('parm'+ _prefix + sEnum.current(), _request);
            }
            if (_prefix && _request.getFieldMap().exists(_prefix + sEnum.current()))
            {
                inventDim.(fieldName2Id(tableNum(InventDim),sEnum.current())) = _request.getFieldValue(_prefix + sEnum.current());
            }
            else if (dc.hasObjectMethod('parm' + sEnum.current()))
            {
                inventDim.(fieldName2Id(tableNum(InventDim),sEnum.current())) = dc.callObject('parm' + sEnum.current(), _request);
            }
            else if (_request.getFieldMap().exists(sEnum.current()))
            {
                inventDim.(fieldName2Id(tableNum(InventDim),sEnum.current())) = _request.getFieldValue(sEnum.current());
            }

        }

        if (inventDim.InventLocationId)
        {
            // SiteId is extracted from Warehouse
            inventDim.InventSiteId = InventLocation::find(inventDim.InventLocationId).InventSiteId;
        }

        // Get the dimension setup for the item

        // Determine if a pallet id or location should be used
        if (tfmInventDimSetup.registerWMSPallet() && !inventDim.LicensePlateId && inventDim.wMSLocationId)
        {
            // Make sure to set the correct from location on the journal line
            // Lookup the current location for the pallet
            // The value of the pallet / location is always stored in the #FromLocation element in the XML

            // Set the values for the pallet and location (where the pallet is placed now)
            inventDim.LicensePlateId   = _request.parmWMSLocationId();
            if (!WHSLicensePlate::exist(inventDim.LicensePlateId))
            {
                WHSLicensePlate::createLicensePlate(inventDim.LicensePlateId);
            }
            inventDim.wMSLocationId    = TFMInventDimHelper::WmsLocationIdFromLicensePlate(inventDim.LicensePlateId).wMSLocationId;

        }

        if (tfmInventDimSetup.registerWMSPallet() && !inventDim.wMSLocationId && inventDim.LicensePlateId)
        {            
            inventDim.wMSLocationId    = TFMInventDimHelper::WmsLocationIdFromLicensePlate(inventDim.LicensePlateId).wMSLocationId;
        }

        if (inventDim.LicensePlateId && !WHSLicensePlate::exist(inventDim.LicensePlateId))
        {
            WHSLicensePlate::createLicensePlate(inventDim.LicensePlateId);
        }
        return inventDim;
    }

public static InventDimParm getAllEnabledDimensions()
{
    InventDimParm parm;
    ListEnumerator enumerator  = InventDim::dimEnabledFieldList().getEnumerator();
    parm.clear();
    while (enumerator.moveNext())
    {
        FieldId dimFieldId = enumerator.current();
        FieldId dimParmFieldId = InventDim::dim2dimParm(dimFieldId);
        parm.(dimParmFieldId) = NoYes::Yes;
    }

    return parm;
}

