public static TFMRegistrationCollectors enabledInventDimCollectors(ItemId _itemId = '', boolean _disableProdDim =false, boolean _disableStorDim = false, boolean _disableTracDim = false, Map _replaceLabels = null, Map _onlineValidationDocuments = null, InventDim _defaultValues = null, boolean _lockValues = false, str _itemIdStringForConditions = '{itemId}')
{
    Map replaceLabels = new Map(Types::String, Types::String);
    Map validationDocs = new Map(Types::String, Types::String);
    SysDictType dictType;        
    InventDimParm parm;
    if (!_disableProdDim && !_disableStorDim && !_disableTracDim)
    {
        parm = TFMInventDimHelper::getAllEnabledDimensions();
    }
    else
    {
        parm = _disableProdDim ? parm  : TFMInventDimHelper::getAllEnabledProductDimensions();
        parm = InventDimParm::orParms(parm, _disableStorDim ? parm  : TFMInventDimHelper::getAllEnabledStorageDimensions());
        parm = InventDimParm::orParms(parm, _disableTracDim ? parm  : TFMInventDimHelper::getAllEnabledTrackingDimensions());
    }
    parm.InventSiteIdFlag = NoYes::No;
    //parm.InventLocationIdFlag = NoYes::No;
    return  TFMInventDimHelper::GetInventDimRegistationCollectors(20,parm,_itemId, _replaceLabels, _onlineValidationDocuments, _defaultValues, _lockValues, _itemIdStringForConditions);
}

/// <summary>
/// Extras the Invent Dim from the Xml Request noode and Item Id.
/// </summary>
public static void ExtractInventDim(InventDim _iDim,
                                    ItemId _itemid,
                                    XmlNode _requestDataNode)
{
    TFMInventDimSetup                   MobInventDimSetup = TFMInventDimSetup::Construct(InventTable::find(_itemId));
    Set									storDims = TFMHelper::fieldGroupToSet(tableNum(InventDim),tableFieldGroupStr(InventDim, StorageDimensions));
    Set									prodDims = TFMHelper::fieldGroupToSet(tableNum(InventDim),tableFieldGroupStr(InventDim, ProductDimensions));
    Set									tracDims = TFMHelper::fieldGroupToSet(tableNum(InventDim),tableFieldGroupStr(InventDim, TrackingDimensions));
    SetEnumerator						sEnum = storDims.getEnumerator();
    FieldName                           fieldName;

    while (sEnum.moveNext())
    {
        fieldName = sEnum.current();
        if (_requestDataNode.getNamedElement( strLwr(fieldName) ) != null)
        {
            _iDim.(fieldName2Id(tableNum(InventDim),fieldName)) = _requestDataNode.getNamedElement( strLwr(fieldName) ).innerText();
        }
        else if (_requestDataNode.getNamedElement( fieldName ) != null)
        {
            _iDim.(fieldName2Id(tableNum(InventDim),fieldName)) = _requestDataNode.getNamedElement( fieldName ).innerText();
        }
    }
    sEnum = prodDims.getEnumerator();
    while (sEnum.moveNext())
    {
        fieldName = sEnum.current();
        if (_requestDataNode.getNamedElement( strLwr(fieldName) ) != null)
        {
            _iDim.(fieldName2Id(tableNum(InventDim),fieldName)) = _requestDataNode.getNamedElement( strLwr(fieldName) ).innerText();
        }
        else if (_requestDataNode.getNamedElement( fieldName ) != null)
        {
            _iDim.(fieldName2Id(tableNum(InventDim),fieldName)) = _requestDataNode.getNamedElement( fieldName ).innerText();
        }
    }
    sEnum = tracDims.getEnumerator();
    while (sEnum.moveNext())
    {
        fieldName = sEnum.current();
        if (_requestDataNode.getNamedElement( strLwr(fieldName) ) != null)
        {
            _iDim.(fieldName2Id(tableNum(InventDim),fieldName)) = _requestDataNode.getNamedElement( strLwr(fieldName) ).innerText();
        }
        else if (_requestDataNode.getNamedElement( fieldName ) != null)
        {
            _iDim.(fieldName2Id(tableNum(InventDim),fieldName)) = _requestDataNode.getNamedElement( fieldName ).innerText();
        }
    }

    if (!_iDim.wMSLocationId && _requestDataNode.getNamedElement( fieldStr(InventDim, wMSLocationId)) != null)
    {

        if (MobInventDimSetup.registerWMSLocation() && !_iDim.wMSLocationId)
        {
            _iDim.wMSLocationId    = _requestDataNode.getNamedElement( fieldStr(InventDim,wMSLocationId) ).text();
        }
    }

    if (!_iDim.InventLocationId && _requestDataNode.getNamedElement( TFMConstants::Warehouse() ) != null)
    {
        _iDim.InventLocationId = _requestDataNode.getNamedElement( TFMConstants::Warehouse() ).text();
    }
    if (!_iDim.InventSiteId && _iDim.InventLocationId)
    {
        // SiteId is extracted from Warehouse
        _iDim.InventSiteId = InventLocation::find(_iDim.InventLocationId).InventSiteId;
    }

    if (_iDim.LicensePlateId && !WHSLicensePlate::exist(_iDim.LicensePlateId))
    {
        WHSLicensePlate::createLicensePlate(_iDim.LicensePlateId);
    }
    if (!_iDim.wMSLocationId && _iDim.LicensePlateId)
    {
        _iDim.wMSLocationId    = TFMInventDimHelper::WmsLocationIdFromLicensePlate(_iDim.LicensePlateId).wMSLocationId;
    }

}

public static TFMRegistrationCollectors GetInventDimRegistationCollectors(int _addStart, InventDimParm _inventDimParm, ItemId _itemId = '', Map _replaceLabels = null, Map _onlineValidationDocuments = null, InventDim _defaultValues = null, boolean _lockValues = false, str _itemIdStringForConditions = '{itemId}')
{
    TFMRegistrationCollectors           collectors = TFMRegistrationCollectors::Construct();
    SysDictType							dictType;
    SysDictField						sdf;
    FieldName							fieldName;
    int									add = _addStart;
    str									labelForField;
    Set									storDims = TFMHelper::fieldGroupToSet(tableNum(InventDim),tableFieldGroupStr(InventDim, StorageDimensions));
    Set									prodDims = TFMHelper::fieldGroupToSet(tableNum(InventDim),tableFieldGroupStr(InventDim, ProductDimensions));
    Set									tracDims = TFMHelper::fieldGroupToSet(tableNum(InventDim),tableFieldGroupStr(InventDim, TrackingDimensions));
    SetEnumerator						sEnum = storDims.getEnumerator();
    TFMRegistrationCollectorList		regCollectorList;
    TFMRegistrationCollector            collector;
    TFMConditions                       conditions;
    InventTable                         inventTable = InventTable::find(_itemId);
    refRecId                            productid = inventTable.Product;
    str                                 listValues;
    TFMCondition                        conditionParent, conditionChild;
    TFMInventDimSetup                   inventDimSetup;

    _inventDimParm.InventStatusFlag = NoYes::No; // Never prompt for Status
    /*if (_inventDimSetup.registerWMSPallet())
    {
        _inventDimParm.WMSLocationIdFlag = NoYes::No; // Never prompt for Location if using Pallet/LP
    }*/
    while (sEnum.moveNext())
    {
        fieldName = sEnum.current();

        if (!_inventDimParm.(InventDim::dim2dimParm(fieldName2Id(tableNum(InventDim),sEnum.current()))))
        {
            continue;
        }
        sdf = new SysDictField(tableNum(InventDim), fieldName2Id(tableNum(InventDim),sEnum.current()));
        add+=10;
        dictType = new SysDictType(sdf.typeId());
        labelForField = dictType.label();
        if (_replaceLabels != null && _replaceLabels.exists(sdf.name()))
        {
            labelForField = _replaceLabels.lookup(sdf.name());
        }


        if (fieldName == fieldStr(InventDim,InventLocationId))
        {
            regCollectorList = new TFMRegistrationCollectorList(5,strLwr(extendedTypeStr(InventLocationId)),"@SYS6437","@SYS6437","@SYS6437");

            regCollectorList.parmDataTable(methodStr(TFMGetReferenceData,WarehouseFilterList));
            regCollectorList.parmDataKeyColumn(extendedtypestr(InventLocationId));
            regCollectorList.parmDataDisplayColumn(extendedtypestr(Name));
            collector = regCollectorList;
        }
        else if (fieldName == fieldStr(InventDim,LicensePlateId))
        {
            collector = TFMRegistrationCollectorText::TextStep(false,add,strLwr(sdf.name()),labelForField,labelForField,dictType.help(),dictType.stringLen(),false,'',TFMInventDimHelper::inventDimField2GS1(sdf.name()));
            collector.parmOnlineValidator('LicensePlateValidation'); // This is a methodStr from the MobOnlineValidator. In the future this should be replaced.
        }
        else
        {
            collector = TFMRegistrationCollectorText::TextStep(false,add,strLwr(sdf.name()),labelForField,labelForField,dictType.help(),dictType.stringLen(),false,'',TFMInventDimHelper::inventDimField2GS1(sdf.name()));
        }
        if (_onlineValidationDocuments != null && _onlineValidationDocuments.exists(sdf.name()))
        {
            collector.setOnlineValidationDocument(_onlineValidationDocuments.lookup(sdf.name()));                
        }
        if (_defaultValues != null && _defaultValues.(fieldName2Id(tableNum(InventDim),sEnum.current())))
        {
            collector.parmDefaultValue(_defaultValues.(fieldName2Id(tableNum(InventDim),sEnum.current())));
            if (_lockValues && SysTest::hasMethod(collector, methodStr(TFMRegistrationCollectorText, parmValidationValues)))
            {
                new SysDictClass(classIdGet(collector)).callObject(methodStr(TFMRegistrationCollectorText, parmValidationValues),collector, _defaultValues.(fieldName2Id(tableNum(InventDim),sEnum.current())));
            }
        }
        conditions = TFMConditions::Construct();

        //conditionParent = TFMCondition::ConstructOperator(classStr(TFMLogicContextAndGate));
        //conditions.addCondition(conditionParent,methodStr(TFMRegistrationCollector,parmActive));

        conditionChild = TFMCondition::Construct(classStr(TFMLogicContextDimensionSetup),[fieldName, _itemIdStringForConditions],'Active');

        conditions.addCondition(conditionChild,methodStr(TFMRegistrationCollector,parmActive));
        if (fieldName == fieldStr(InventDim,WMSLocationId))
        {
            // Suppress WMSLocation if LicensePlate dim is active
            conditionParent = TFMCondition::ConstructOperator(classStr(TFMLogicContextAndGate));
            conditions.addCondition(conditionParent,methodStr(TFMRegistrationCollector,parmActive));
            conditions.addLink(conditionChild, conditionParent,methodStr(TFMRegistrationCollector,parmActive));
            conditionChild = TFMCondition::ConstructOperator(classStr(TFMLogicContextInverterOperator));
            conditions.addCondition(conditionChild,methodStr(TFMRegistrationCollector,parmActive));
            conditions.addLink(conditionChild, conditionParent,methodStr(TFMRegistrationCollector,parmActive));
            conditionParent = TFMCondition::Construct(classStr(TFMLogicContextDimensionSetup),[fieldStr(InventDim, LicensePlateId), _itemIdStringForConditions],'Active');
            conditions.addCondition(conditionParent,methodStr(TFMRegistrationCollector,parmActive));
            conditions.addLink(conditionParent, conditionChild,methodStr(TFMRegistrationCollector,parmActive));
        }
        /*conditions.addLink(conditionChild,conditionParent, methodStr(TFMRegistrationCollector,parmActive));

        conditionChild = TFMCondition::ConstructOperator(classStr(TFMLogicContextInverterOperator));
        conditions.addCondition(conditionChild,methodStr(TFMRegistrationCollector,parmActive));
        conditions.addLink(conditionChild,conditionParent, methodStr(TFMRegistrationCollector,parmActive));

        conditionParent = TFMCondition::Construct(classStr(TFMLogicContextDimensionSetup),[fieldName],'AllowBlank');
        conditions.addCondition(conditionParent,methodStr(TFMRegistrationCollector,parmActive));
        conditions.addLink(conditionParent, conditionChild,methodStr(TFMRegistrationCollector,parmActive));*/

        conditions.addCondition(TFMCondition::Construct(classStr(TFMLogicContextDimensionSetup),[fieldName, _itemIdStringForConditions],'AllowBlank'),methodStr(TFMRegistrationCollector,parmOptional));
        collector.parmConditions(conditions);
        collector.addTableFieldOrigin(tableStr(InventDim), sEnum.current());
        collectors.addCollector(collector);               
    }

    sEnum = prodDims.getEnumerator();
    while (sEnum.moveNext())
    {
        fieldName = sEnum.current();
        listValues = '';
        if (!_inventDimParm.(fieldName2Id(tableNum(InventDimParm),TFMInventDimHelper::flagFieldName(fieldName))))
        {
            continue;
        }
        sdf = new SysDictField(tableNum(InventDim), fieldName2Id(tableNum(InventDim),sEnum.current()));
        add+=10;
        dictType = new SysDictType(sdf.typeId());
        labelForField = dictType.label();
        if (_replaceLabels != null && _replaceLabels.exists(sdf.name()))
        {
            labelForField = _replaceLabels.lookup(sdf.name());
        }
        /*if (productid)
        {
            listValues = TFMInventDimHelper::getProductDimensionValues(productid,sEnum.current()); //TODO: Convert to condition object
        }*/
        collector = TFMRegistrationCollectorList::ListStep(false,add, strlwr(sdf.name()) ,labelForField,labelForField,dictType.help(),listValues,false,'',';',TFMInventDimHelper::inventDimField2GS1(sdf.name()));
        if (_onlineValidationDocuments != null && _onlineValidationDocuments.exists(sdf.name()))
        {
            collector.setOnlineValidationDocument(_onlineValidationDocuments.lookup(sdf.name()));
        }
        if (_defaultValues != null && _defaultValues.(fieldName2Id(tableNum(InventDim),sEnum.current())))
        {
            collector.parmDefaultValue(_defaultValues.(fieldName2Id(tableNum(InventDim),sEnum.current())));
        }
        conditions = TFMConditions::Construct();
        conditions.addCondition(TFMCondition::Construct(classStr(TFMLogicContextDimensionSetup),[fieldName, _itemIdStringForConditions],'active'),methodStr(TFMRegistrationCollector,parmActive) );
        conditions.addCondition(TFMCondition::Construct(classStr(TFMLogicContextDimensionSetup),[fieldName, _itemIdStringForConditions],'AllowBlank'),methodStr(TFMRegistrationCollector,parmOptional) );
        conditions.addCondition(TFMCondition::Construct(classStr(TFMLogicContextDimensionSetup),[fieldName, _itemIdStringForConditions],'ProductDimensionValues'),methodStr(TFMListValuesAndDataTable, parmListValues) );
        conditions.addCondition(TFMCondition::Construct(classStr(TFMLogicContextDimensionSetup),[fieldName, _itemIdStringForConditions],'HasValueInContext'),methodStr(TFMRegistrationCollector, getSetAddAsAdditionalValue) );
        conditions.addCondition(TFMCondition::Construct(classStr(TFMLogicContextDimensionSetup),[fieldName, _itemIdStringForConditions],'ValueFromContext'),methodStr(TFMRegistrationCollector, parmDefaultValue) );
        collector.parmConditions(conditions);

        collector.addTableFieldOrigin(tableStr(InventDim), sEnum.current());
        collectors.addCollector(collector);

    }
    sEnum = tracDims.getEnumerator();
    while (sEnum.moveNext())
    {
        fieldName = sEnum.current();

        if (!_inventDimParm.(fieldName2Id(tableNum(InventDimParm),TFMInventDimHelper::flagFieldName(fieldName))))
        {
            continue;
        }
        sdf = new SysDictField(tableNum(InventDim), fieldName2Id(tableNum(InventDim),sEnum.current()));
        add+=10;
        dictType = new SysDictType(sdf.typeId());
        labelForField = dictType.label();
        if (_replaceLabels != null && _replaceLabels.exists(sdf.name()))
        {
            labelForField = _replaceLabels.lookup(sdf.name());
        }
        collector = TFMRegistrationCollectorText::TextStep(false,add,strLwr(sdf.name()),labelForField,labelForField,dictType.help(),dictType.stringLen(),false,'',TFMInventDimHelper::inventDimField2GS1(sdf.name()));
        if (_onlineValidationDocuments != null && _onlineValidationDocuments.exists(sdf.name()))
        {
            collector.setOnlineValidationDocument(_onlineValidationDocuments.lookup(sdf.name()));
        }
        if (_defaultValues != null && _defaultValues.(fieldName2Id(tableNum(InventDim),sEnum.current())))
        {
            collector.parmDefaultValue(_defaultValues.(fieldName2Id(tableNum(InventDim),sEnum.current())));
            if (_lockValues && SysTest::hasMethod(collector, methodStr(TFMRegistrationCollectorText, parmValidationValues)))
            {
                new SysDictClass(classIdGet(collector)).callObject(methodStr(TFMRegistrationCollectorText, parmValidationValues),collector, _defaultValues.(fieldName2Id(tableNum(InventDim),sEnum.current())));
            }
        }
        conditions = TFMConditions::Construct();
        conditions.addCondition(TFMCondition::Construct(classStr(TFMLogicContextDimensionSetup),[fieldName, _itemIdStringForConditions],'active'),methodStr(TFMRegistrationCollector,parmActive) );
        conditions.addCondition(TFMCondition::Construct(classStr(TFMLogicContextDimensionSetup),[fieldName, _itemIdStringForConditions],'AllowBlank'),methodStr(TFMRegistrationCollector,parmOptional) );
        collector.parmConditions(conditions);
        collector.addTableFieldOrigin(tableStr(InventDim), sEnum.current());
        collectors.addCollector(collector);
    }

    return collectors;
}

public static boolean SerialNumberIsactiveInSalesOnly(ItemId _itemId)
{
    TFMInventDimSetup setup = TFMInventDimSetup::Construct(InventTable::find(_itemId));

    return (setup.registerSerialNumberSales() && !setup.registerSerialNumber());
}
